//! Real signed source/result, native review, continuation, resource lease,
//! Driver, canonical delivery and reconciliation. Provider HTTP is synthetic.
use super::*;
use crate::pet_runtime::{result_disclosure_policy::Policy,result_disclosure::Observe,admission::Approved,plans,native_plan_review};
fn ready(s:&Setup,memory:bool)->(Record,Record,crate::pet_runtime::messages::Receipt){ready_criteria(s,memory,None)}
fn ready_criteria(s:&Setup,memory:bool,criteria:Option<Vec<String>>)->(Record,Record,crate::pet_runtime::messages::Receipt){let(p,g,r,i)=super::result_disclosure::completed_criteria(s,memory,criteria);let(c,t)=s.observe().unwrap();let observe:Observe=Arc::new(move||Ok((c.clone(),t.clone())));let review=current_store(s).prepare_native_plan(&s.f.path.join("authority"),&g.id,"ai_ollama",&g.revision,vec![i],nonce().unwrap(),crate::assistant_memory::now()).unwrap().with_result_data(&s.f.path.join("authority"),&s.f.path.join("notes.json"),observe,crate::assistant_memory::now()).unwrap();let mut a=review.approve(crate::assistant_memory::now(),Arc::new(||true)).unwrap();let g=a.confirm(&current_store(s),crate::assistant_memory::now()).unwrap().receipt.record;assert_eq!(g.schema_version,32);(p,g,r)}
fn observe(s:&Setup)->Observe{let(c,t)=s.observe().unwrap();Arc::new(move||Ok((c.clone(),t.clone())))}
fn policy(s:&Setup,g:&Record)->Policy{let p=&g.plans[0];let st=&p.steps[0];let data=crate::pet_runtime::result_disclosure::Captured::at(&s.f.path.join("authority"),&s.f.path.join("notes.json"),g,crate::pet_runtime::messages::Cause{task_id:p.task_id.clone(),plan_id:p.id.clone(),step_id:st.id.clone()},crate::pet_runtime::derived_result_plan::Arguments::parse(st.operation.as_ref().unwrap()).unwrap(),plans::fingerprint(g).unwrap(),observe(s),crate::assistant_memory::now()).unwrap();data.policy(g).unwrap()}
fn evidence(s:&Setup,g:&Record,p:&Policy)->Evidence{let at=crate::assistant_memory::now();let d=crate::pet_runtime::admission_tests::descriptor(g,at);let data=crate::pet_runtime::result_delivery_data::Captured::at(&s.f.path.join("authority"),&s.f.path.join("notes.json"),g,p.clone(),observe(s),at).unwrap();Evidence::observe_result(g,&d,"a".repeat(64),at,data).unwrap()}
fn bounds(p:&Policy)->Budget{Budget{deadline_at:p.arguments.expires_at,max_model_calls:0,max_tool_calls:1,max_output_bytes:4096,max_tokens:None,max_cost_micros:None,payment:Payment::RuntimeOnly}}
fn review(s:&Setup,g:&Record,p:&Policy,b:Budget)->std::result::Result<GoalReview,Denial>{let at=crate::assistant_memory::now();let(g,c)=current_store(s).prepare_continuation_review(&s.f.path.join("authority"),&g.id,&g.spec.owner.pet_id,&g.revision,at,false).unwrap().unwrap();{let e=evidence(s,&g,p);GoalReview::prepare_result_disclosure(&g,e,b,c,nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now())}}
fn approve(s:&Setup,g:&Record,p:&Policy)->Approved{review(s,g,p,bounds(p)).unwrap().approve_with_scopes(g,evidence(s,g,p),None,Some(crate::pet_runtime::work_disclosure::Consent::BoundedResultDisclosure),crate::assistant_memory::now()).unwrap()}
fn queue(s:&Setup,g:&Record,p:&Policy)->Record{let a=approve(s,g,p);assert_eq!(a.spec().schema_version,14);assert!(a.spec().binding_format());let cert=s.a.certify(&a,g,crate::assistant_memory::now()).unwrap();let q=current_store(s).enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;assert_eq!(q.schema_version,33);assert_eq!(q.id,g.id);assert_eq!(q.spec,g.spec);q}
fn own(s:&Setup,q:&Record,p:&Policy)->(Record,Arc<Owned>){let e=evidence(s,q,p);let at=crate::assistant_memory::now();let controller=Controller::new().unwrap();let pending=controller.prepare_memory_fixture(q,&s.f.path.join("authority"),&s.f.path.join("contexts"),&s.f.path.join("notes.json"),&s.main,&e,nonce().unwrap(),at,Arc::new(|_,_,_|Validity::Current)).unwrap();let(r,o)=pending.claim(&current_store(s),&s.a,&evidence(s,q,p),crate::assistant_memory::now()).unwrap();assert!(r.record.admissions.last().unwrap().lease.as_ref().unwrap().model.is_empty());(r.record,Arc::new(o.unwrap()))}
struct NativeEnv{config:crate::pet_config::Configuration,settings:Mutex<crate::settings::Settings>,captures:AtomicUsize,drains:AtomicUsize,notices:Mutex<Vec<Status>>}
impl Environment for NativeEnv{
 fn capture(&self,_:&Owned)->model::Result<Capture>{self.captures.fetch_add(1,Ordering::AcqRel);panic!("derived reply must never invoke or resolve a model")}
 fn configuration(&self)->model::Result<crate::pet_config::Configuration>{Ok(self.config.clone())}
 fn target(&self)->model::Result<Arc<crate::spotify::goal::Target>>{panic!("no media/system target authorized")}
 fn decide(&self,_:crate::pet_runtime::recipe_decisions::Source)->Option<crate::pet_runtime::recipe_decisions::Decision>{panic!("exact bounded disclosure already approved in its own native admission")}
 fn notify(&self,s:&Status){self.notices.lock().unwrap().push(s.clone());}
 fn peer_configuration(&self)->model::Result<(crate::pet_config::Configuration,crate::settings::Settings)>{Ok((self.config.clone(),self.settings.lock().unwrap().clone()))}
 fn drained(&self,_:&crate::pet_runtime::lease_controller::DrainProof)->model::Result<()>{self.drains.fetch_add(1,Ordering::AcqRel);Ok(())}
}
fn latest_bytes(s:&Setup,g:&Record)->Vec<u8>{fs::read(s.f.path.join("authority").join(format!("{}.json",g.admissions.last().unwrap().spec.decision_id))).unwrap()}
fn body(s:&Setup,g:&Record)->Value{serde_json::from_slice::<Value>(&latest_bytes(s,g)).unwrap()["body"].clone()}
fn environment(s:&Setup)->Arc<NativeEnv>{Arc::new(NativeEnv{config:s.config.clone(),settings:Mutex::new(s.settings.clone()),captures:AtomicUsize::new(0),drains:AtomicUsize::new(0),notices:Mutex::new(vec![])})}
#[test]fn same_goal_signed_disclosure_delivers_once_without_inference_and_settles_cumulative_original_budget(){
 let s=Setup::new();let(parent,g,source)=ready(&s,true);let p=policy(&s,&g);let old=s.bytes(&g);let q=queue(&s,&g,&p);let(g,owner)=own(&s,&q,&p);let env=environment(&s);let d=Driver::new(owner.clone(),Arc::new(current_store(&s)),env.clone()).unwrap();assert_eq!(run(d.run()).unwrap().phase,Phase::Completed);let done=current_store(&s).read(&g.id,"ai_ollama").unwrap();assert_eq!(done.state,State::Completed);assert!(done.completion.is_some());assert_eq!(done.admissions.len(),2);assert_eq!(done.admissions[0].spec.schema_version,12);let b=body(&s,&done);assert_eq!(b["schemaVersion"],25);assert_eq!(b["messages"]["schemaVersion"],6);assert_eq!(b["messages"]["entries"].as_array().unwrap().len(),1);assert_eq!(b["budgetUsage"]["attempts"][0]["kind"],"tool");assert_eq!(b["budgetUsage"]["attempts"][0]["phase"],"settled");assert_eq!(env.captures.load(Ordering::Acquire),0);assert_eq!(env.drains.load(Ordering::Acquire),1);assert_eq!(owner.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());
 let row=done.admissions.last().unwrap();let r=s.a.message_at(&row.spec,row.proof.as_ref().unwrap(),&p.cause.plan_id,&p.cause.step_id).unwrap().unwrap();assert_eq!(r.envelope().schema_version,6);assert_eq!(r.envelope().text,"🌍");assert!(!r.envelope().provider_use_authorized);assert_eq!(r.envelope().derived_result.as_ref(),Some(&p.published()));assert!(!serde_json::to_string(&r).unwrap().contains("DO_NOT_COPY_FULL_MEMORY_IN_DISCLOSURE"));let received=s.a.message_inbox(&p.recipient.pet_id,None,32,crate::assistant_memory::now()).unwrap();assert!(received.items.iter().any(|i|i.receipt==r));
 let bytes=latest_bytes(&s,&done);let v=reconcile(&s,&parent,&source);assert_eq!(v.consumed.as_ref().unwrap().model_calls,1);assert_eq!(v.consumed.as_ref().unwrap().tool_calls,1);assert_eq!(v.held.unwrap(),Allowance::default());assert_eq!(s.a.message_ack(&row.spec,row.proof.as_ref().unwrap(),&r.scope).unwrap(),Some(r));assert_eq!(latest_bytes(&s,&done),bytes);assert_eq!(fs::read(s.f.path.join("authority").join(format!("{}.json",done.admissions[0].spec.decision_id))).unwrap(),old);assert_eq!(current_store(&s).read(&done.id,"ai_ollama").unwrap().id,g.id);
 let mut legacy=done.clone();legacy.schema_version=32;assert!(legacy.validate().is_err());
}
#[test]fn f2_work_metadata_and_missing_scope_cannot_approve_disclosure_or_expand_any_original_dimension(){
 let s=Setup::new();let(_,g,_)=ready(&s,false);let p=policy(&s,&g);let before=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);
 for consent in [None,Some(crate::pet_runtime::work_disclosure::Consent::BoundedWorkDisclosure)]{assert!(review(&s,&g,&p,bounds(&p)).unwrap().approve_with_scopes(&g,evidence(&s,&g,&p),None,consent,crate::assistant_memory::now()).is_err());}
 assert!(review(&s,&g,&p,bounds(&p)).unwrap().approve_with_scopes(&g,evidence(&s,&g,&p),Some(GoalConsent::BoundedGoalContext),Some(crate::pet_runtime::work_disclosure::Consent::BoundedResultDisclosure),crate::assistant_memory::now()).is_err());
 for dimension in ["models","tools","output","deadline"]{let mut b=bounds(&p);match dimension{"models"=>b.max_model_calls=1,"tools"=>b.max_tool_calls=2,"output"=>b.max_output_bytes=8192,_=>b.deadline_at=p.arguments.expires_at+1};assert!(review(&s,&g,&p,b).is_err(),"{dimension}");}assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);
}
#[test]fn source_cancel_after_review_denies_own_intent_without_sharing_or_renewing_prior_f2(){
 let s=Setup::new();let(parent,g,source)=ready(&s,false);let p=policy(&s,&g);let approval=approve(&s,&g,&p);let before=s.bytes(&g);let c=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(parent.clone(),&parent.admissions[0].spec.decision_id,&source.envelope().message_id,crate::pet_runtime::delegation::BranchAction::Cancel,crate::assistant_memory::now()).unwrap();c.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();assert!(s.a.certify(&approval,&g,crate::assistant_memory::now()).is_err());assert_eq!(s.bytes(&g),before);assert!(body(&s,&g).get("messages").is_none());
}
#[test]fn revoked_memory_or_target_before_dispatch_causes_no_delivery_and_drains_the_original_native_owner(){
 for changed in ["memory","target"]{let s=Setup::new();let(_,g,_)=ready(&s,true);let p=policy(&s,&g);let q=queue(&s,&g,&p);let(g,o)=own(&s,&q,&p);let env=environment(&s);let d=Driver::new(o.clone(),Arc::new(current_store(&s)),env.clone()).unwrap();
 if changed=="memory"{let mut n=super::result_disclosure::note();n["revision"]=json!(2);super::result_disclosure::notes(&s,n,2);}else{env.settings.lock().unwrap().active_integrations.retain(|id|id!=&p.recipient.pet_id);}
 let _=run(d.run());let current=current_store(&s).read_control(&g.id,"ai_ollama").unwrap();assert!(body(&s,&current).get("messages").is_none());assert_eq!(env.captures.load(Ordering::Acquire),0);assert_eq!(o.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty(),"{changed}");assert!(current.completion.is_none());}
}

#[test]fn delivery_receipt_cannot_certify_unknown_semantic_criteria_or_keep_a_model_running(){
 let s=Setup::new();let(_,g,_)=ready_criteria(&s,false,Some(vec![crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION.into(),"Demonstrate the semantic analysis is correct; model text is not evidence".into()]));let p=policy(&s,&g);let q=queue(&s,&g,&p);let(g,o)=own(&s,&q,&p);let env=environment(&s);let d=Driver::new(o.clone(),Arc::new(current_store(&s)),env.clone()).unwrap();assert_eq!(run(d.run()).unwrap().phase,Phase::AwaitingVerification);let current=current_store(&s).read(&g.id,"ai_ollama").unwrap();assert_eq!(current.state,State::Paused);assert!(current.completion.is_none());let b=body(&s,&current);assert_eq!(b["schemaVersion"],25);assert_eq!(b["phase"],"closed");assert!(b.get("nativeCompletion").is_none());assert_eq!(b["messages"]["entries"].as_array().unwrap().len(),1);assert_eq!(env.captures.load(Ordering::Acquire),0);assert_eq!(o.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());
}

