fn requested_disclosure_once(s:&Setup,g:&Record,p:&Policy,expected:u32){
 use crate::pet_runtime::admission::StartScope;
 let at=crate::assistant_memory::now();let before=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);
 let missing=review(s,g,p,bounds(p)).unwrap().with_execution_start(Some(crate::pet_runtime::planning::Start::WhenAvailable)).unwrap();assert!(missing.approve_with_scopes(g,evidence(s,g,p),None,None,at).is_err());assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);
 let choice=review(s,g,p,bounds(p)).unwrap().with_execution_start(Some(crate::pet_runtime::planning::Start::WhenAvailable)).unwrap();assert_eq!(choice.proposal().execution_start.as_ref().unwrap().scope,StartScope::ResultDisclosure);
 let approved=choice.approve_with_scopes(g,evidence(s,g,p),None,Some(crate::pet_runtime::work_disclosure::Consent::BoundedResultDisclosure),crate::assistant_memory::now()).unwrap();assert_eq!(approved.spec().schema_version,expected);assert!(approved.spec().execution_requested());assert!(!crate::pet_runtime::readiness_api::requested_inference(approved.spec()));
 let cert=s.a.certify(&approved,g,crate::assistant_memory::now()).unwrap();let q=current_store(s).enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;assert_eq!(q.schema_version,46);let original=q.admissions.last().unwrap().spec.clone();let original_bytes=latest_bytes(s,&q);
 let ack=current_store(s).acknowledge_requested(&q.id,&q.spec.owner.pet_id,&q.revision,crate::assistant_memory::now()).unwrap();assert_eq!(ack.revision,q.revision);assert_eq!(latest_bytes(s,&q),original_bytes);assert!(ack.admissions.last().unwrap().lease.is_none());
 let(q,owner)=own(s,&ack,p);let env=environment(s);let driver=Driver::new(owner.clone(),Arc::new(current_store(s)),env.clone()).unwrap();assert_eq!(run(driver.run()).unwrap().phase,Phase::Completed);let done=current_store(s).read(&q.id,&q.spec.owner.pet_id).unwrap();assert_eq!(done.schema_version,46);assert_eq!(model::fingerprint(&done.admissions.last().unwrap().spec).unwrap(),model::fingerprint(&original).unwrap());assert_eq!(env.captures.load(Ordering::Acquire),0);assert_eq!(owner.workers(),0);assert!(s.main.runtime_resources().busy().unwrap().is_empty());let b=body(s,&done);assert_eq!(b["budgetUsage"]["attempts"].as_array().unwrap().len(),1);assert_eq!(b["budgetUsage"]["attempts"][0]["kind"],"tool");assert_eq!(b["budgetUsage"]["attempts"][0]["phase"],"settled");
 let mut forged=original;forged.execution_start.as_mut().unwrap().scope=StartScope::FiniteResponse;assert!(!forged.binding_format());
}
#[test]fn requested_direct_result_start_requires_own_disclosure_scope_and_runs_once_without_inference(){
 let s=Setup::new();let(_,g,_)=ready(&s,false);let p=policy(&s,&g);requested_disclosure_once(&s,&g,&p,14);
}
